world node {
    use aap:caps/types@0.1.0.{moderated-query, conversation-context};

    import aap:caps/kb-read@0.1.0;

    export run: func(query: moderated-query) -> conversation-context;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;

struct Node;

/// Truncate a string to at most `max` bytes, respecting char boundaries.
fn clamp(mut s: String, max: usize) -> String {
    if s.len() > max {
        let mut end = max;
        while end > 0 && !s.is_char_boundary(end) {
            end -= 1;
        }
        s.truncate(end);
    }
    s
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let inner = query.query;

        // `requires len(query.question) <= 512` holds of the input; we still
        // clamp defensively so `ensures len(question) <= 512` holds of the
        // output unconditionally.
        let question = clamp(inner.question, 512);

        // The node's entire authority: read-only lookup against the
        // 'knowledge-base' store. No write, no listing, no other sink.
        let mut knowledge = kb_read::lookup(&question);

        // `ensures present(knowledge)`: guarantee a non-empty result.
        if knowledge.is_empty() {
            knowledge.push(String::from("(no matching knowledge-base entries)"));
        }

        ConversationContext {
            intent: inner.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

